// One row per new client for the "New Clients" tab. Tel reviews it and adds the client to Airtable.
function manila(iso){ const d=iso?new Date(iso):new Date();
  const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(d).reduce((o,x)=>(o[x.type]=x.value,o),{});
  return p.year+'-'+p.month+'-'+p.day+' '+p.hour+':'+p.minute; }
const V = $('Verify').first().json || {};
const REQ = $('When Executed by Another Workflow').first().json || {};
const CC = $('Check Conflicts').first().json || {};
const t = String(CC.final_summary || REQ.summary || '').split(' / ');
const client = String(CC.final_client || '').trim() || (t.length >= 3 ? t[1].trim() : '');
const desc = String(REQ.description || '');
return [{ json: {
  'Client': client,
  'Status': 'For Review',
  'Booked by': ((desc.match(/Booked by:\s*([^|]+)/) || [])[1] || '').trim(),
  'Project': String(t[0] || '').trim(),
  'Session Type': String(REQ.session_type || ''),
  'Department': String(REQ.department || ''),
  'Booking Date': (CC.final_start || REQ.start_iso) ? manila(CC.final_start || REQ.start_iso).slice(0, 10) : '',
  'Room(s)': Array.isArray(REQ.rooms) ? REQ.rooms.join(', ') : String(REQ.rooms || ''),
  'Calendar Title': String(V.title || REQ.summary || ''),
  'Event ID': String(V.event_id || ''),
  'Added': manila()
} }];

// v51 (Howard, 2026-09-28 - option 2 of the eval report): Prepare Booking. Every guard in Check Conflicts has run
// (engineer, client, title, rooms, dates, conflicts) and nothing was created. This renders THE summary the
// requester approves - one fixed format, the calendar title always first, and a check code over the booking lines.
// At the yes, main's "Prepared Booking" reads this exact message back from Slack and Book Session books those
// details, whatever the model sends. Before this the model wrote the summary: 5 date formats, the title shown in
// 16% of summaries, and one live booking titled differently from the summary that was approved.
// --- Prepared booking summary: shared by Book Session "Render Summary" and main "Prepared Booking" (v51/v163) ---
// The summary a requester approves is the booking. Code renders it in one fixed format and ends it with a short
// check code over the booking lines; at the yes, main reads that exact message back, re-checks the code, and hands
// those details to Book Session. Keep PB_FIELDS, pbNorm and pbCode identical in both nodes.
const PB_SALT = '4539361661025d1d';
const PB_FIELDS = ['Title', 'Client', 'Project', 'Session Type', 'Date', 'Time', 'Room', 'Engineer', 'Arranger', 'Department', 'Booking Type', 'Booked by', 'Override'];
const pbNorm = s => String(s == null ? '' : s).replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/[*_]/g, '').replace(/\s+/g, ' ').trim();
const pbCode = f => { let h = 0x811c9dc5; const s = PB_SALT + '|' + PB_FIELDS.map(k => pbNorm(f[k])).join('|');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const REQ = $('When Executed by Another Workflow').first().json || {};
const CC = $('Check Conflicts').first().json || {};
let DP = {}; try { DP = $('Decide Preempt').first().json || {}; } catch (e) {}
const segs = String(CC.final_description || REQ.description || '').split('|').map(s => s.trim()).filter(Boolean);
const seg = re => { const s = segs.find(x => re.test(x)); return s ? s.replace(re, '').trim() : ''; };
const title = String(CC.final_summary || REQ.summary || '').trim();
const tparts = title.split(' / ');
const st = String(REQ.session_type || '').trim();
const internal = !st;                                   // Lobby / Conference Room: no client, engineer or session type
const loc = /^(localization|qc)\b/i.test(st);
const start = String(CC.final_start || REQ.start_iso || ''), end = String(CC.final_end || REQ.end_iso || '');
const allDay = REQ.all_day === true || String(REQ.all_day).toLowerCase() === 'true' || /^\d{4}-\d{2}-\d{2}$/.test(start);
const dayOf = iso => { const d = /^\d{4}-\d{2}-\d{2}$/.test(iso) ? new Date(iso + 'T12:00:00+08:00') : new Date(iso);
  return new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Manila', weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(d); };
const hm = iso => new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Manila', hour: 'numeric', minute: '2-digit' }).format(new Date(iso));
const rooms = String(REQ.rooms || '').split(',').map(r => r.trim()).filter(Boolean).join(', ');
const client = String(CC.final_client || '').trim();
let clientRows = []; try { clientRows = $('Get Client').all().map(i => (i && i.json) || {}); } catch (e) {}
const newClient = !!client && client.toLowerCase() !== String(tparts[0] || '').toLowerCase()
  && !clientRows.some(r => r.id) && !clientRows.some(r => r.error);
const override = REQ.room_override === true || String(REQ.room_override).toLowerCase() === 'true';
const F = {
  'Title': title,
  'Client': internal ? '' : (client || 'None'),
  'Project': internal ? '' : String(tparts[0] || '').trim(),
  'Session Type': st,
  'Date': start ? dayOf(start) : '',
  'Time': allDay ? 'All day' : (start && end ? hm(start) + ' – ' + hm(end) : ''),
  'Room': rooms,
  'Engineer': seg(/^engineer\s*:\s*/i),
  'Arranger': seg(/^arranger\s*:\s*/i),
  'Department': String(REQ.department || '').trim(),
  'Booking Type': internal ? '' : String(REQ.bookingType || '').trim(),
  'Booked by': seg(/^booked by\s*:\s*/i),
  'Override': override ? 'yes' : ''
};
const L = ['*' + F['Title'] + '*'];
for (const k of ['Client', 'Project', 'Session Type', 'Date', 'Time', 'Room', 'Engineer', 'Arranger', 'Department', 'Booking Type', 'Booked by']) {
  if (F[k]) L.push('*' + (k === 'Project' && loc ? 'Project Code' : k) + ':* ' + F[k]);
}
const notes = [];
const _am = Number(CC.assumed_minutes) || 0;
if (_am > 0) { const _h = Math.floor(_am / 60), _m = _am % 60;
  notes.push('Assuming ' + (_h ? _h + ' hour' + (_h === 1 ? '' : 's') : '') + (_h && _m ? ' ' : '') + (_m ? _m + ' minutes' : '') + ', the usual ' + st + ' length - tell me if it should be different.'); }
if (newClient) notes.push(client + ' is not in the client list yet - it will be added for review.');
if (override) notes.push(rooms + ' is not a room normally used for ' + (st || 'this') + ' - booking it as you asked.');
// PENDING 30 (2026-09-28): a session type whose Room Requirements pairs it with a holding room (Celebrity Recording:
// "Large, pair with one or more conference room as holding areas") gets a note - from Airtable, not the prompt.
try {
  let _R2 = {}; try { _R2 = JSON.parse(String(REQ.reference_data || '{}')); } catch (e) {}
  const _ty = (_R2.types || []).find(x => String(x.type || '').toLowerCase() === st.toLowerCase());
  const _hasConf = String(rooms).split(',').some(x => (_R2.rooms || []).some(rr => rr.common && rr.name.toLowerCase() === x.trim().toLowerCase()));
  if (_ty && /holding|conference/i.test(String(_ty.req || '')) && !_hasConf)
    notes.push(st + ' usually pairs with a conference room as a holding area - if you want one, say which (Likha, Katha or Salin) before you confirm.');
} catch (e) {}
let needsConsent = false;
if (DP && DP.offer === true && DP.open) {
  needsConsent = true;
  const o = DP.open;
  notes.push(o.kind === 'MBOOTH'
    ? (o.room + ' has a standing hold (' + (o.incumbentTitle || o.approverName || 'the holder') + '). If you confirm, I will ask ' + (o.approverName || 'the holder') + ' to release it for this session, and book it once they agree.')
    : (o.room + ' is already booked then (' + (o.incumbentTitle || 'another session') + '). Your session outranks it, so if you confirm I will ask them to move, and book it once they do.'));
}
const out = L.join('\n') + (notes.length ? '\n\n' + notes.map(n => '*Note:* ' + n).join('\n') : '')
  + '\n\n_check ' + pbCode(F) + '_'
  + '\n\nReply only with "yes" to book, or "no" to change anything.\nConfirm to book.';
return [{ json: { status: 'PREPARED', summary_text: out, title: F['Title'], needs_consent: needsConsent, new_client: newClient,
  human: 'The summary is ready and is sent to the requester automatically, exactly as prepared. Do not write a summary, '
       + 'or anything else about this booking, yourself. When they reply yes, call Book Session to create it.' } }];

// v52 (2026-09-28, speed): main already read the Bookers table this turn and sends it as staff_data, so the
// same ~1.1 s Airtable read is not repeated here. Named "All Bookers" so every reference to it still works; the
// Airtable read ("All Bookers (Airtable)") runs only when a caller sends no staff list (Book Series, consent).
const REQ = $('When Executed by Another Workflow').first().json || {};
let list = null;
try { const s = JSON.parse(String(REQ.staff_data || '')); if (Array.isArray(s) && s.length) list = s; } catch (e) {}
if (list) return list.filter(f => f && f.Name).map(f => ({ json: { fields: f } }));
let rows = [];
try { rows = $('All Bookers (Airtable)').all(); } catch (e) {}
return rows.length ? rows : [{ json: {} }];

