// --- engineer and arranger must be real people in Bookers ----------------
// QA 2026-09-25: asked for "Daryl", the model wrote "Daryl Javier (Music Engineer)" - a surname it
// invented - and titled it DJ. Nobody called Javier exists. Earlier it put the nickname "Drey" in the
// title (PENDING 31). Every name the model supplies is resolved against the Bookers table here:
// an exact name, a "Goes by" alias from Info, initials, or a unique first name becomes the canonical
// Name and Initials. Anything else is refused - an engineer not on the staff list is never written.
{
  const _norm = s => String(s || '').toLowerCase().replace(/[.\s]+/g, ' ').trim();
  const _staff = (function () {
    try { return $('All Bookers').all().map(it => (it.json && it.json.fields) || {}).filter(f => f.Name); }
    catch (e) { return []; }
  })().map(f => {
    const info = String(f.Info || '');
    const gb = info.match(/goes by\s+(.*)$/i);
    const aliasSrc = gb ? gb[1] : info;
    const aliases = aliasSrc.split(/,|\band\b/i).map(_norm).filter(Boolean);
    const name = String(f.Name).trim();
    return { name, initials: String(f.Initials || '').trim(), first: _norm(name.split(/\s+/)[0]),
             keys: [_norm(name), _norm(f.Initials)].concat(aliases).filter(Boolean) };
  });
  const _split = raw => { const m = String(raw || '').trim().match(/^(.*?)\s*(\([^)]*\))?\s*$/); return { who: (m && m[1] || '').trim(), role: (m && m[2]) ? ' ' + m[2] : '' }; };
  const _resolve = who => {
    const g = _norm(who);
    if (!g) return null;
    let hit = _staff.filter(p => _norm(p.name) === g);
    if (hit.length !== 1) hit = _staff.filter(p => p.keys.indexOf(g) !== -1);
    if (hit.length !== 1) hit = _staff.filter(p => p.first === g);
    return hit.length === 1 ? hit[0] : null;
  };
  const _suggest = who => {
    const toks = _norm(who).split(' ').filter(t => t.length > 1);
    return _staff.filter(p => toks.some(t => p.first === t || p.keys.indexOf(t) !== -1)).map(p => p.name);
  };
  const _segs = String(REQ.description || '').split('|');
  const _segIdx = re => _segs.findIndex(s => re.test(s.trim()));
  const _eIdx = _segIdx(/^engineer\s*:/i), _aIdx = _segIdx(/^arranger\s*:/i);
  const _engRaw = String(REQ.engineer || '').trim() || (_eIdx !== -1 ? _segs[_eIdx].trim().replace(/^engineer\s*:\s*/i, '') : '');
  const _arrRaw = _aIdx !== -1 ? _segs[_aIdx].trim().replace(/^arranger\s*:\s*/i, '') : '';
  const _checks = [['engineer', _engRaw], ['arranger', _arrRaw]].filter(c => _split(c[1]).who);
  if (_checks.length && !_staff.length) {
    return [{ json: { verdict:'REJECTED', reason:'ENGINEER_UNVERIFIED',
      human:'Nothing was booked - the staff list could not be read, so the engineer could not be checked. Tell the requester it failed and to try again.' } }];
  }
  const _found = {};
  for (const [role, raw] of _checks) {
    const p = _split(raw);
    const hit = _resolve(p.who);
    if (!hit) {
      const sug = _suggest(p.who);
      return [{ json: { verdict:'REJECTED', reason:'ENGINEER_UNKNOWN', role, given: p.who, suggestions: sug,
        human:'Nothing was booked. "' + p.who + '" is not on the Hit Productions staff list, so they cannot be the ' + role + '. '
            + (sug.length ? 'Did the requester mean ' + sug.join(' or ') + '? ' : '')
            + 'Confirm the ' + role + ' with the requester, then present the summary again using the exact name from the staff list. Never add a surname they did not give.' } }];
    }
    _found[role] = { hit, role: p.role };
  }
  if (_found.engineer) {
    const e = _found.engineer;
    REQ.engineer = e.hit.name + e.role;
    if (_eIdx !== -1) _segs[_eIdx] = ' Engineer: ' + e.hit.name + e.role + ' ';
  }
  if (_found.arranger) {
    const a = _found.arranger;
    _segs[_aIdx] = ' Arranger: ' + a.hit.name + a.role + ' ';
  }
  if (_found.engineer || _found.arranger) REQ.description = _segs.join('|').replace(/^\s+/, '');
  const _tp = String(REQ.summary || '').split(' / ');
  // Localization titles are two segments, "Project Code / Initials", and were never corrected here.
  // 2026-09-26 (Howard, NET-KUBA): the model rebuilt the title as "NET-KUBA / JP" for Jek Panganiban,
  // whose recorded initials are FP - it made initials from his name - and that went on the calendar.
  // Since v49 a studio booking may have no client, "PROJECT / Initials" (Howard, 2026-09-28), which has the
  // same two-segment shape as Localization. Any two-segment title on a session type gets the same correction;
  // internal rooms use " - " and carry no session type, so they are never touched.
  const _twoSeg = _tp.length === 2 && String(REQ.session_type || '').trim() !== '';
  if (_found.engineer && (_tp.length === 3 || _twoSeg) && _found.engineer.hit.initials) {
    const last = _tp.length - 1;
    const parts = _tp[last].split(' x ');
    parts[0] = _found.engineer.hit.initials;
    if (_found.arranger && _found.arranger.hit.initials) parts[1] = _found.arranger.hit.initials;
    _tp[last] = parts.join(' x ');
    REQ.summary = _tp.join(' / ');
  }
}

// --- on-behalf bookings still need a real, distinct client ----------------
// The person a session is booked FOR (Booked by: X (for Y)) is a colleague, never the
// client, and must not land in the title Client segment. Prompt-only rules did not hold:
// the model laundered the booked-for name into the client/title when no client was given
// (Howard, 2026-09-23). Enforced here, only for External studio bookings that name a for-person.
// Since v49 clients are optional (Howard, 2026-09-28): no client is fine and the title drops the client
// segment. What is still refused is the booked-for colleague standing in as the client.
const bookedFor = ((String(REQ.description || '').match(/\(for\s+([^)]+)\)/i) || [])[1] || '').trim();
if (bookedFor && String(REQ.bookingType || '').trim().toLowerCase() === 'external') {
  const clientNow = String(REQ.client || '').trim();
  const _tsegs = String(REQ.summary || '').split(' / ');
  const titleClient = _tsegs.length === 3 ? _tsegs[1].trim() : '';
  // The booked-for name now arrives canonical from Booked For ("Japs Concepcion"), so a client slot
  // holding just "Japs" would slip past an exact compare. Match the person's first name and "Goes by"
  // aliases from Bookers too (2026-09-25).
  const _n = s => String(s || '').toLowerCase().replace(/[.\s]+/g, ' ').trim();
  const _forKeys = (function () {
    const k = [_n(bookedFor), _n(bookedFor.split(/\s+/)[0])];
    try {
      const f = $('All Bookers').all().map(i => (i.json && i.json.fields) || {}).find(x => _n(x.Name) === _n(bookedFor));
      const gb = f && String(f.Info || '').match(/goes by\s+(.*)$/i);
      if (gb) gb[1].split(/,|\band\b/i).map(_n).filter(a => a.length >= 3).forEach(a => k.push(a));
    } catch (e) {}
    return k.filter(Boolean);
  })();
  const isFor = (s) => !!s && _forKeys.indexOf(_n(s)) !== -1;
  // v54 (Howard, 2026-09-28): the in-house arrangers are both staff (Bookers) and clients (Clients, "Hit In-house
  // Arranger") - booking a studio for an arranger's own project makes them both the booked-for person and the client,
  // and that is legitimate. So the refusal only stands when the booked-for person is NOT a client on record.
  const _bfIsClient = (function () {
    try { return $('Get Client').all().some(i => i.json && i.json.id && _n((i.json.fields || {}).Name) === _n(bookedFor)); } catch (e) { return false; }
  })();
  if (!_bfIsClient && (isFor(clientNow) || isFor(titleClient))) {
    return [{ json: { verdict:'REJECTED', reason:'MISSING_CLIENT',
      human:'Nothing was booked. ' + bookedFor + ' is who this session is booked FOR, not the client - so ' + bookedFor + ' must not be the client and must not appear in the calendar title. Ask the requester who the client is. If there is none, leave the client empty and use PROJECT / initials as the title. Present the summary again.' } }];
  }
}

